const MAX_OCCURRENCE_RANGE_DAYS = 366;

function validateSeatingLayout(
    firstClassRows: number,
    businessRows: number,
    premiumEconomyRows: number,
    economyRows: number,
    seatPattern: string
): string {
    const rowCounts = [firstClassRows, businessRows, premiumEconomyRows, economyRows];
    if (rowCounts.some(rowCount => !Number.isInteger(rowCount) || rowCount < 0)) {
        throw new Error("Row configurations must be non-negative integers.");
    }
    if (rowCounts.every(rowCount => rowCount === 0)) {
        throw new Error("At least one seating row is required.");
    }

    const trimmedPattern = seatPattern.trim().toUpperCase();
    if (!trimmedPattern) {
        throw new Error("Seat pattern is required.");
    }

    if (!/^[A-Z-]+$/.test(trimmedPattern)) {
        throw new Error("Seat pattern must only contain uppercase letters and hyphens.");
    }

    const letters = trimmedPattern.replace(/[^A-Z]/g, "");
    if (letters.length === 0) {
        throw new Error("Seat pattern must contain at least one seat letter.");
    }
    if (!/^[A-Z]+(?:-[A-Z]+)*$/.test(trimmedPattern)) {
        throw new Error("Seat pattern must contain seat-letter groups separated by single hyphens.");
    }

    const lettersSet = new Set(letters);
    if (lettersSet.size !== letters.length) {
        throw new Error("Seat pattern letters must be unique.");
    }

    return trimmedPattern;
}

function assertOccupiedSeatsFitLayout(
    passengers: Array<{ seatNumber: string }>,
    totalRows: number,
    seatPattern: string
) {
    const seatLetters = new Set(seatPattern.replace(/-/g, '').split(''));

    for (const passenger of passengers) {
        const match = /^(\d+)([A-Z])$/.exec(passenger.seatNumber);
        const row = match ? Number(match[1]) : 0;
        const letter = match?.[2];
        if (!match || row < 1 || row > totalRows || !letter || !seatLetters.has(letter)) {
            throw new Error(
                `Occupied seat ${passenger.seatNumber} is not present in the requested layout.`
            );
        }
    }
}

export async function saveFlightScheduleAction(data: {
    id?: number;
    flightNumber: string;
    airline: string;
    from: string;
    to: string;
    departureTime: string;
    returnTime: string | null;
    daysOfWeek: number[];
    price: string;
    firstClassRows?: number | null;
    businessRows?: number | null;
    premiumEconomyRows?: number | null;
    economyRows?: number | null;
    seatPattern?: string | null;
}) {
    const session = await getServerSession(authOptions);
    if (session?.user?.role !== 'ADMIN') throw new Error("Unauthorized");

    // Server-side validation
    if (!data.flightNumber || !data.airline || !data.from || !data.to || !data.departureTime || !data.price) {
        throw new Error("Please fill in all required fields.");
    }

    const timeRegex = /^([0-1]?[0-9]|2[0-3]):[0-5][0-9]$/;
    if (!timeRegex.test(data.departureTime)) {
        throw new Error("Departure time must be in HH:MM format (24-hour).");
    }

    if (data.returnTime && !timeRegex.test(data.returnTime)) {
        throw new Error("Return time must be in HH:MM format (24-hour) or left empty.");
    }

    if (!Array.isArray(data.daysOfWeek) || data.daysOfWeek.length === 0) {
        throw new Error("Please select at least one day of the week.");
    }

    const firstClassRows = data.firstClassRows !== undefined && data.firstClassRows !== null ? Number(data.firstClassRows) : 2;
    const businessRows = data.businessRows !== undefined && data.businessRows !== null ? Number(data.businessRows) : 4;
    const premiumEconomyRows = data.premiumEconomyRows !== undefined && data.premiumEconomyRows !== null ? Number(data.premiumEconomyRows) : 4;
    const economyRows = data.economyRows !== undefined && data.economyRows !== null ? Number(data.economyRows) : 20;
    const seatPattern = data.seatPattern || "ABC-DEF";

    const normalizedSeatPattern = validateSeatingLayout(
        firstClassRows,
        businessRows,
        premiumEconomyRows,
        economyRows,
        seatPattern
    );

    let savedSchedule;
    if (data.id) {
        savedSchedule = await prisma.flightSchedule.update({
            where: { id: data.id },
            data: {
                flightNumber: data.flightNumber,
                airline: data.airline,
                from: data.from,
                to: data.to,
                departureTime: data.departureTime,
                returnTime: data.returnTime,
                daysOfWeek: data.daysOfWeek,
                price: data.price,
                firstClassRows,
                businessRows,
                premiumEconomyRows,
                economyRows,
                seatPattern: normalizedSeatPattern
            }
        });
    } else {
        savedSchedule = await prisma.flightSchedule.create({
            data: {
                flightNumber: data.flightNumber,
                airline: data.airline,
                from: data.from,
                to: data.to,
                departureTime: data.departureTime,
                returnTime: data.returnTime,
                daysOfWeek: data.daysOfWeek,
                price: data.price,
                firstClassRows,
                businessRows,
                premiumEconomyRows,
                economyRows,
                seatPattern: normalizedSeatPattern
            }
        });
    }

    // Pre-generate flights for the next 30 days from this schedule
    const today = new Date();
    const utcToday = new Date(Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), today.getUTCDate()));
    for (let i = 0; i < 30; i++) {
        const date = new Date(utcToday);
        date.setUTCDate(utcToday.getUTCDate() + i);
        const dayOfWeek = date.getUTCDay();

        if (savedSchedule.daysOfWeek.includes(dayOfWeek)) {
            const dateStr = date.toISOString().split('T')[0];
            const departureDate = new Date(`${dateStr}T${savedSchedule.departureTime}:00Z`);

            let returnDate = null;
            if (savedSchedule.returnTime) {
                const retDate = new Date(date);
                retDate.setUTCDate(date.getUTCDate() + 7);
                const retDateStr = retDate.toISOString().split('T')[0];
                returnDate = new Date(`${retDateStr}T${savedSchedule.returnTime}:00Z`);
            }

            // Check if flight instance already exists
            const existingInstance = await prisma.flight.findFirst({
                where: {
                    flightNumber: savedSchedule.flightNumber,
                    departureDate: departureDate
                }
            });

            if (!existingInstance) {
                try {
                    await prisma.flight.create({
                        data: {
                            flightNumber: savedSchedule.flightNumber,
                            airline: savedSchedule.airline,
                            from: savedSchedule.from,
                            to: savedSchedule.to,
                            departureDate,
                            returnDate,
                            price: savedSchedule.price,
                            status: 'ON_TIME',
                            firstClassRows,
                            businessRows,
                            premiumEconomyRows,
                            economyRows,
                            seatPattern: normalizedSeatPattern
                        }
                    });
                } catch (error) {
                    if (!(error && typeof error === 'object' && 'code' in error && error.code === 'P2002')) {
                        throw error;
                    }
                }
            }
        }
    }

    revalidatePath('/');
    revalidatePath('/flights');
    revalidatePath('/admin/flights');

    return savedSchedule;
}

