            departureTime: '08:00',
            returnTime: null,
            daysOfWeek: [5, 1],
            price: '$350',
            firstClassRows: 3,
            businessRows: 3,
            premiumEconomyRows: 4,
            economyRows: 20,
            seatPattern: ' abc-def '
        })).toMatchObject({
            flightNumber: 'AA101',
            airline: 'Example Air',
            daysOfWeek: [1, 5],
            seatPattern: 'ABC-DEF'
        });
        expect(scheduleSchema.safeParse({
            flightNumber: 'AA101', airline: 'Air', from: 'A', to: 'B',
            departureTime: '08:00', returnTime: null, daysOfWeek: [1, 1], price: '$1'
        }).success).toBe(false);
    });

