export interface ActionValidationFailure {
    ok: false;
    error: {
        code: 'VALIDATION_ERROR';
        message: string;
        fields: Record<string, string[]>;
    };
}

export function isActionValidationFailure(value: unknown): value is ActionValidationFailure {
    if (!value || typeof value !== 'object') return false;
    const candidate = value as Partial<ActionValidationFailure>;
    return candidate.ok === false && candidate.error?.code === 'VALIDATION_ERROR';
}

export function actionValidationFailure(
    message: string,
    field = '_root'
): ActionValidationFailure {
    return {
        ok: false,
        error: {
            code: 'VALIDATION_ERROR',
            message,
            fields: { [field]: [message] }
        }
    };
}
"use client"

import React, { useState, useEffect, useTransition } from 'react';
import { useRouter } from 'next/navigation';
import PointsActivityTable from "@/components/ui/pointsActivityTable";
import NextStatusChart from "@/components/ui/charts/nextStatusChart";
import PointsHistoryChart from "@/components/ui/charts/pointsHistoryChart";
import { cancelBookingAction, deleteReviewAction, toggleFavoriteCityGuideAction, changeBookingSeatsAction, getOccupiedSeatsAction } from '@/app/actions';
import { isActionValidationFailure } from '@/lib/actionResult';
import { PointsActivityDisplayData } from '@/lib/types/PointsActivity';

interface Flight {
    id: number;
    flightNumber: string;
    airline: string;
    from: string;
    to: string;
    departureDate: Date | string;
    returnDate: Date | string | null;
    price: string;
    firstClassRows?: number | null;
    businessRows?: number | null;
    premiumEconomyRows?: number | null;
    economyRows?: number | null;
    seatPattern?: string | null;
}

interface Passenger {
    id: string;
    firstName: string;
    lastName: string;
    dateOfBirth: Date | string;
    passportNumber: string;
    gender: string;
    seatNumber: string;
    cabinClass: string;
}

interface Booking {
    id: number;
    createdAt: Date | string;
    status: string; // "CONFIRMED" or "CANCELLED"
    totalPrice: string;
    flightId: number | null;
    flight: Flight | null;
    passengers: Passenger[];
}

interface CityGuide {
    id: number;
    city: string;
    country: string;
    description: string;
    coverImage: string | null;
}

interface UserFavorite {
    id: string;
    cityGuideId: number;
    cityGuide: CityGuide;
}

interface Review {
    id: string;
    content: string;
    rating: number;
    cityGuide: CityGuide;
    createdAt: Date | string;
}

interface ProfileClientProps {
    userName: string;
    userAvatar: string;
    currentStatus: string;
    currentPoints: number;
    bookings: Booking[];
    favorites: UserFavorite[];
    reviews: Review[];
    activityData: PointsActivityDisplayData[];
    monthlyHistory: PointsActivityDisplayData[];
}

export default function ProfileClient({
    userName,
    userAvatar,
    currentStatus,
    currentPoints,
    bookings,
    favorites,
    reviews,
    activityData,
    monthlyHistory
}: ProfileClientProps) {
    const router = useRouter();
    const [isPending, startTransition] = useTransition();

