import { prisma } from '@/lib/prisma';
import { assertSeatAvailableForCabin } from '@/lib/seatLayout';
import { lockFlightForUpdate } from '@/lib/flightLock';
import { flightBookingServiceSchema, parseInput } from '@/lib/validation';
import { calculateBookingTotal } from '@/lib/bookingPricing';

export interface PassengerInput {
  firstName: string;
  lastName: string;
  dateOfBirth: Date | string;
  passportNumber: string;
  gender: string;
  seatNumber: string;
  cabinClass: string;
}

export default class FlightBookingService {
    async bookFlight(bookingData: { 
        flightId: number;
        userId: string;
        passengers: PassengerInput[];
        idempotencyKey: string;
    }) {
        const { flightId, userId, passengers, idempotencyKey } = parseInput(
            flightBookingServiceSchema,
            bookingData
        );

        // Run booking inside a database transaction to ensure atomic execution
        const savedBooking = await prisma.$transaction(async (tx) => {
            await lockFlightForUpdate(tx, flightId);
            const flight = await tx.flight.findUnique({ where: { id: flightId } });
            if (!flight) throw new Error("Flight not found");

            const existingRequest = await tx.booking.findFirst({
                where: { userId, idempotencyKey },
                include: { passengers: true }
            });
            if (existingRequest) {
                return { ...existingRequest, wasCreated: false };
            }

            if (flight.status === 'CANCELLED' || flight.departureDate.getTime() <= Date.now()) {
                throw new Error('Flight is not available for booking.');
            }

            // Check if any seat is already booked on this flight
            const requestedSeats = passengers.map(p => p.seatNumber);
            if (new Set(requestedSeats).size !== requestedSeats.length) {
                throw new Error("Duplicate seats selected in request.");
            }

            for (const passenger of passengers) {
                assertSeatAvailableForCabin(
                    passenger.seatNumber,
                    passenger.cabinClass,
                    flight
                );
            }

            const existingBookings = await tx.booking.findMany({
                where: { flightId, status: { not: "CANCELLED" } },
                include: { passengers: true }
            });

            const occupiedSeats = new Set(
                existingBookings
                    .flatMap(b => b.passengers)
                    .map(p => p.seatNumber)
            );

            for (const seat of requestedSeats) {
                if (occupiedSeats.has(seat)) {
                    throw new Error(`Seat ${seat} is already occupied on this flight.`);
                }
            }

            const total = calculateBookingTotal(
                flight.price,
                passengers.map(passenger => ({
                    cabinClass: passenger.cabinClass as 'ECONOMY' | 'PREMIUM_ECONOMY' | 'BUSINESS' | 'FIRST'
                }))
            );

            // Create booking with nested passengers
            const booking = await tx.booking.create({
                data: {
                    flightId,
                    userId,
                    totalPrice: total.formatted,
                    paymentIntentId: null,
                    idempotencyKey,
                    passengers: {
                        create: passengers.map(p => ({
                            firstName: p.firstName,
                            lastName: p.lastName,
                            dateOfBirth: new Date(p.dateOfBirth),
                            passportNumber: p.passportNumber,
                            gender: p.gender,
                            seatNumber: p.seatNumber,
                            cabinClass: p.cabinClass,
                            flightId
                        }))
                    }
                },
                include: {
                    passengers: true
                }
            });
            return { ...booking, wasCreated: true };
        });

        return savedBooking;
    }
}
export const CABIN_FARE_PERCENT = {
    ECONOMY: 100,
    PREMIUM_ECONOMY: 150,
    BUSINESS: 200,
    FIRST: 300
} as const;

export type CabinClass = keyof typeof CABIN_FARE_PERCENT;

export function parsePriceToCents(price: string): number {
    const normalized = price.trim();
    if (!/^\$?(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d{1,2})?$/.test(normalized)) {
        throw new Error('Flight price is invalid.');
    }

    const numeric = normalized.replace(/[$,]/g, '');
    const [whole, fraction = ''] = numeric.split('.');
    const cents = Number(whole) * 100 + Number(fraction.padEnd(2, '0'));
    if (!Number.isSafeInteger(cents) || cents < 0) {
        throw new Error('Flight price is invalid.');
    }
    return cents;
}

export function calculatePassengerFareCents(basePriceCents: number, cabinClass: CabinClass): number {
    return Math.round(basePriceCents * CABIN_FARE_PERCENT[cabinClass] / 100);
}

export function formatPrice(cents: number): string {
    return new Intl.NumberFormat('en-US', {
        style: 'currency',
        currency: 'USD',
        minimumFractionDigits: cents % 100 === 0 ? 0 : 2,
        maximumFractionDigits: cents % 100 === 0 ? 0 : 2
    }).format(cents / 100);
}

export function calculateBookingTotal(
    basePrice: string,
    passengers: Array<{ cabinClass: CabinClass }>
): { cents: number; formatted: string } {
    const basePriceCents = parsePriceToCents(basePrice);
    const cents = passengers.reduce(
        (sum, passenger) => sum + calculatePassengerFareCents(basePriceCents, passenger.cabinClass),
        0
    );
    return { cents, formatted: formatPrice(cents) };
}
import { PointsActivityData, StartingPoints } from "./data/PointsActivityData";
import { PointsActivityDisplayData } from "./types/PointsActivity";
import { Booking, Flight } from "@prisma/client";
import { parsePriceToCents } from "./bookingPricing";

type BookingWithFlight = Booking & { flight: Flight | null };

class PointsActivityService {
  private bookings: BookingWithFlight[] | null;
  private startingPoints: number;

  constructor(bookings?: BookingWithFlight[], startingPoints?: number) {
    this.bookings = bookings !== undefined ? bookings : null;
    this.startingPoints = startingPoints !== undefined ? startingPoints : StartingPoints;
  }

  private parsePrice(priceStr: string | null | undefined): number {
    if (!priceStr) return 0;
    try {
      return Math.floor(parsePriceToCents(priceStr) / 100);
    } catch {
      return 0;
    }
  }

  getCurrentPoints(): number {
    if (this.bookings === null) {
      return PointsActivityData.reduce((total, activity) => total + activity.points, this.startingPoints);
    }
    return this.bookings.reduce((total, booking) => {
      if (booking.status === 'CANCELLED') return total;
      const priceStr = booking.totalPrice || booking.flight?.price;
      const price = this.parsePrice(priceStr);
      return total + price;
    }, this.startingPoints);
  }

  getCurrentStatus(): string {
    const points = this.getCurrentPoints();
    if (points < 1000) return "Bronze";
    if (points < 3000) return "Silver";
    if (points < 6000) return "Gold";
    return "Platinum";
  }

  getPointsActivity(): PointsActivityDisplayData[] {
    if (this.bookings === null) {
      const displayData: PointsActivityDisplayData[] = PointsActivityData.map((activity) => ({
        description: activity.description,
        date: activity.date.toLocaleDateString(),
        points: activity.points
      }));
      displayData.push({
        description: 'Starting Points',
        date: '',
        points: this.startingPoints
      });
      return displayData;
    }

    const displayData: PointsActivityDisplayData[] = [];
    this.bookings.forEach((booking) => {
      const flight = booking.flight;
      const priceStr = booking.totalPrice || flight?.price;
      const points = this.parsePrice(priceStr);
      const baseDesc = flight 
        ? `✈️ ${flight.airline} ${flight.flightNumber} (${flight.from} → ${flight.to})`
        : '✈️ Flight Booking';

      if (booking.status === 'CANCELLED') {
        // 1. Show original positive booking credit
        displayData.push({
          description: baseDesc,
          date: new Date(booking.createdAt).toLocaleDateString(),
          points: points
        });
        // 2. Show cancellation debit
        displayData.push({
          description: `❌ Cancelled: ${baseDesc.replace('✈️ ', '')}`,
          date: new Date(booking.createdAt).toLocaleDateString(),
          points: -points
        });
      } else {
        displayData.push({
          description: baseDesc,
          date: new Date(booking.createdAt).toLocaleDateString(),
          points: points
        });
      }
    });

    displayData.push({
      description: 'Starting Points',
      date: '',
      points: this.startingPoints
    });

    return displayData;
  }

  getMonthlyPointsActivity(): PointsActivityDisplayData[] {
    if (this.bookings === null) {
      const monthlyPointsMap: { [key: string]: number } = {};
      PointsActivityData.forEach((activity) => {
        const monthYear = activity.date.toLocaleString('default', { month: 'short', year: 'numeric' });
        monthlyPointsMap[monthYear] = (monthlyPointsMap[monthYear] || 0) + activity.points;
      });

      const sortedMonths = Object.keys(monthlyPointsMap).sort((a, b) => new Date(a).getTime() - new Date(b).getTime());
      const startDate = new Date(sortedMonths[0]);
      startDate.setMonth(startDate.getMonth() - 1);
      const endDate = new Date(sortedMonths[sortedMonths.length - 1]);
      const allMonths: string[] = [];
      for (let date = new Date(startDate); date <= endDate; date.setMonth(date.getMonth() + 1)) {
        allMonths.push(date.toLocaleString('default', { month: 'short', year: 'numeric' }));
      }

      let cumulativePoints = this.startingPoints;
      return allMonths.map(monthYear => {
        if (monthlyPointsMap[monthYear]) {
          cumulativePoints += monthlyPointsMap[monthYear];
        }
        return {
          description: monthYear,
          date: monthYear,
          points: cumulativePoints
        };
      });
    }

    const monthlyPointsMap: { [key: string]: number } = {};
    this.bookings.forEach((booking) => {
      const date = new Date(booking.createdAt);
      const monthYear = date.toLocaleString('default', { month: 'short', year: 'numeric' });
      const priceStr = booking.totalPrice || booking.flight?.price;
      const points = this.parsePrice(priceStr);
      if (booking.status === 'CANCELLED') {
        // Cancellation balances out to 0 net points for this month
        monthlyPointsMap[monthYear] = (monthlyPointsMap[monthYear] || 0) + points - points;
      } else {
        monthlyPointsMap[monthYear] = (monthlyPointsMap[monthYear] || 0) + points;
      }
    });

    const sortedMonths = Object.keys(monthlyPointsMap).sort((a, b) => new Date(a).getTime() - new Date(b).getTime());
    let allMonths: string[] = [];

    if (sortedMonths.length > 0) {
      const startDate = new Date(sortedMonths[0]);
      startDate.setMonth(startDate.getMonth() - 1);
      const endDate = new Date(sortedMonths[sortedMonths.length - 1]);
      for (let date = new Date(startDate); date <= endDate; date.setMonth(date.getMonth() + 1)) {
        allMonths.push(date.toLocaleString('default', { month: 'short', year: 'numeric' }));
      }
    } else {
      const now = new Date();
      allMonths = [
        new Date(now.getFullYear(), now.getMonth() - 1).toLocaleString('default', { month: 'short', year: 'numeric' }),
        now.toLocaleString('default', { month: 'short', year: 'numeric' })
      ];
    }

    let cumulativePoints = this.startingPoints;
    return allMonths.map(monthYear => {
      if (monthlyPointsMap[monthYear]) {
        cumulativePoints += monthlyPointsMap[monthYear];
      }
      return {
        description: monthYear,
        date: monthYear,
        points: cumulativePoints
      };
    });
  }
}

export default PointsActivityService;
export async function getFlightRoutesAction() {
    // Distinct origin/destination pairs that actually have flight schedules, so the
    // booking form can offer only reachable routes.
    return await prisma.flightSchedule.findMany({
        distinct: ['from', 'to'],
        select: { from: true, to: true },
        orderBy: [{ from: 'asc' }, { to: 'asc' }],
    });
}

export async function bookFlightAction(bookingData: { 
    flightId: number;
    passengers: PassengerInput[];
    idempotencyKey: string;
}) {
    const session = await getServerSession(authOptions);
    const userId = session?.user?.id;
    if (!userId) throw new Error("Unauthorized");
    const parsed = parseActionInput(bookingRequestSchema, bookingData);
    if (!parsed.ok) return parsed;
    bookingData = parsed.data as typeof bookingData;

    const result = await flightBookingService.bookFlight({
        flightId: bookingData.flightId,
        userId,
        passengers: bookingData.passengers,
        idempotencyKey: bookingData.idempotencyKey
    });

    try {
        const flight = await prisma.flight.findUnique({ where: { id: bookingData.flightId } });
        if (flight && result.wasCreated) {
            const points = Math.floor(parsePriceToCents(result.totalPrice) / 100);
            await prisma.notification.create({
                data: {
                    userId,
                    title: `Booking Confirmed: ${flight.airline} ${flight.flightNumber}`,
                    message: `Successfully booked flight ${flight.flightNumber} from ${flight.from} to ${flight.to}. Earned +${points} status points.`,
                    type: "POINTS"
                }
            });
        }
    } catch (err) {
        console.error("Failed to generate points notification:", err);
    }

    revalidatePath('/profile');
    return result;
}

export async function getOccupiedSeatsAction(flightId: number) {
    flightId = parseInput(numericIdSchema, flightId);
    const passengers = await prisma.passenger.findMany({
        where: {
            booking: {
                flightId,
    }

    const updated = await prisma.$transaction(async (tx) => {
        if (booking.flightId) await lockFlightForUpdate(tx, booking.flightId);
        const lockedBooking = await tx.booking.findUnique({
            where: { id: bookingId },
            select: { status: true }
        });
        if (!lockedBooking) throw new Error("Booking not found");
        if (lockedBooking.status === "CANCELLED") throw new Error("Booking is already cancelled");

        const passengers = await tx.passenger.findMany({
            where: { bookingId }
        });

        for (const passenger of passengers) {
            await tx.passenger.update({
                where: { id: passenger.id },
                data: { seatNumber: `CANCELLED-${passenger.id}` }
            });
        }

        return await tx.booking.update({
            where: { id: bookingId },
            data: { status: "CANCELLED" }
        });
    });

    try {
        const flight = booking.flight;
        if (flight && booking.userId) {
            const rawPrice = booking.totalPrice || flight.price;
            const points = Math.floor(parsePriceToCents(rawPrice) / 100);
            await prisma.notification.create({
                data: {
                    userId: booking.userId,
                    title: `Booking Cancelled: ${flight.airline} ${flight.flightNumber}`,
                    message: `Booking for flight ${flight.flightNumber} has been cancelled. Deducted -${points} status points.`,
                    type: "POINTS"
                }
            });
        }
    } catch (err) {
        console.error("Failed to generate cancellation notification:", err);
    }

    revalidatePath('/profile');
    revalidatePath('/admin');
    return updated;
}

